import React, { useState, useEffect } from 'react';

// Import các màn hình con từ thư mục components
import MovieList from './components/MovieList';
import ShowtimeScreen from './components/ShowtimeScreen';
import SeatScreen from './components/SeatScreen';
import AuthScreen from './components/AuthScreen';

function App() {
  const [movies, setMovies] = useState([]);
  const [showtimes, setShowtimes] = useState([]);
  const [seats, setSeats] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  const [currentScreen, setCurrentScreen] = useState('movie-list');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [selectedShowtime, setSelectedShowtime] = useState(null);

  useEffect(() => {
    // Đọc trực tiếp file ở thư mục gốc bằng cách fetch ngược qua cổng 3000 công khai
    fetch('http://localhost:3000/../database.json')
      .then((res) => {
        if (!res.ok) throw new Error("Không thể tải file");
        return res.json();
      })
      .then((data) => {
        setMovies(data.movies || []);
        setShowtimes(data.showtimes || []);
        setSeats(data.seats || []);
        setBookings(data.bookings || []);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Lỗi đọc database.json ở gốc:", err);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
        <div className="text-center">
          <div className="spinner-border text-primary mb-2" role="status"></div>
          <h5 className="fw-bold text-secondary">Đang kết nối database ngoài thư mục gốc...</h5>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-light min-vh-100 pb-5">
      {/* NAVBAR */}
      <nav className="navbar navbar-dark bg-dark mb-5 shadow">
        <div className="container">
          <span className="navbar-brand mb-0 h1 fw-bold text-warning fs-3" style={{ cursor: 'pointer', letterSpacing: '1px' }} onClick={() => setCurrentScreen('movie-list')}>
            🎬 BETA CINEMA
          </span>
        </div>
      </nav>

      {/* ĐIỀU HƯỚNG MÀN HÌNH */}
      <div className="container">
        {currentScreen === 'movie-list' && (
          <MovieList movies={movies} showtimes={showtimes} onSelectMovie={(m) => { setSelectedMovie(m); setCurrentScreen('showtime-list'); }} onGoToAuth={() => setCurrentScreen('auth')} />
        )}
        {currentScreen === 'showtime-list' && (
          <ShowtimeScreen movie={selectedMovie} showtimes={showtimes} onSelectShowtime={(st) => { setSelectedShowtime(st); setCurrentScreen('seat-plan'); }} onBack={() => setCurrentScreen('movie-list')} />
        )}
        {currentScreen === 'seat-plan' && (
          <SeatScreen showtime={selectedShowtime} movie={selectedMovie} seats={seats} bookings={bookings} onBookingSuccess={(newB) => setBookings([...bookings, ...newB])} onBack={() => setCurrentScreen('showtime-list')} />
        )}
        {currentScreen === 'auth' && (
          <AuthScreen onBack={() => setCurrentScreen('movie-list')} />
        )}
      </div>
    </div>
  );
}

export default App;
